async function c(n){const l=Object.entries(n),a=await Promise.allSettled(l.map(([,e])=>Promise.resolve().then(()=>e.load()))),t={},r=[];if(l.forEach(([e,u],i)=>{const s=a[i];if(s.status==="fulfilled"){t[e]=s.value;return}r.push({key:e,label:u.label||e,error:s.reason})}),!r.length)return{values:t,error:null};const o=new Error(`部分数据读取失败：${r.map(e=>e.label).join("、")}`);if(o.failures=r,r.length===l.length)throw o;return{values:t,error:o}}export{c as l};
